(5521996, 797518, 31637, '<td valign="top">Nice house! and exposed well</td>', 'Nice house! and exposed well', '2009-06-10 01:15:29.000000', NULL, 1),
(5521999, 797870, 31637, '<td valign="top">Beautiful place, love the black and white conversion subtle light and even inclusion of trees.</td>', 'Beautiful place, love the black and white conversion subtle light and even inclusion of trees.', '2009-06-10 01:17:15.000000', NULL, 1),
(5522003, 798013, 98022, '<td valign="top">Great abstract shot. Wonderful clarity and detail. I really like the contrast between the blue and white paint. Top three for me.</td>', 'Great abstract shot. Wonderful clarity and detail. I really like the contrast between the blue and white paint. Top three for me.', '2009-06-10 01:18:44.000000', NULL, 1),
