(5522098, 797239, 106726, '<td valign="top">wonderful colors :) - 8</td>', 'wonderful colors :) - 8', '2009-06-10 02:33:49.000000', NULL, 1),
(5522114, 797965, 29486, '<td valign="top">Way too light (due to the bright sky) and overall too busy (background)</td>', 'Way too light (due to the bright sky) and overall too busy (background)', '2009-06-10 02:49:54.000000', NULL, 1),
(5522117, 798020, 29486, '<td valign="top">The wall is very distracting. It''s so big and bright, it really becomes the focus.</td>', 'The wall is very distracting. It''s so big and bright, it really becomes the focus.', '2009-06-10 02:50:51.000000', NULL, 1),
(5522118, 798032, 29486, '<td valign="top">The white line in the sky is very distracting. The building on the left should have been cropped. A 50% zoom on this to focus on the nice art deco would have been much better for the time of day this was taken.</td>', 'The white line in the sky is very distracting. The building on the left should have been cropped. A 50% zoom on this to focus on the nice art deco would have been much better for the time of day this was taken.', '2009-06-10 02:52:47.000000', NULL, 1),
