(5525841, 797378, 106653, '<td valign="top">love the color effect.  composition is great.  lighting is good.  great mood created!</td>', 'love the color effect.  composition is great.  lighting is good.  great mood created!', '2009-06-12 21:07:11.000000', NULL, 1),
