(5525845, 797260, 106653, '<td valign="top">Wow! Fantastic lighting!  I probably would have just lifted the camera more -- to get less ground and more sky, and then the composition would have been better, too.</td>', 'Wow! Fantastic lighting!  I probably would have just lifted the camera more -- to get less ground and more sky, and then the composition would have been better, too.', '2009-06-12 21:11:00.000000', NULL, 1),
(5525847, 798123, 106653, '<td valign="top">Ooh! Cool! I love the focus/lack there of.  Good composition.</td>', 'Ooh! Cool! I love the focus/lack there of.  Good composition.', '2009-06-12 21:14:49.000000', NULL, 1),
(5525849, 798158, 106653, '<td valign="top">Great composition and lighting.  It even looks good as a thumbnail!</td>', 'Great composition and lighting.  It even looks good as a thumbnail!', '2009-06-12 21:18:17.000000', NULL, 1),
