(5531542, 797980, 106484, '<td valign="top">There''s quite a lot of noise in this shot, and i''m not exactly sure what i''m looking at.</td>', 'There''s quite a lot of noise in this shot, and i''m not exactly sure what i''m looking at.', '2009-06-16 17:17:41.000000', NULL, 1),
(5531543, 797982, 106484, '<td valign="top">There''s a strange effect going on in the shot. Perhaps this has been over sharpened? Nice composition though.</td>', 'There''s a strange effect going on in the shot. Perhaps this has been over sharpened? Nice composition though.', '2009-06-16 17:18:29.000000', NULL, 1),
(5531545, 797522, 106484, '<td valign="top">Sky is way overexposed, was this taken in raw mode? You may have been able to get back a little of the sky in raw. Or a graduated ND filter may have helped.</td>', 'Sky is way overexposed, was this taken in raw mode? You may have been able to get back a little of the sky in raw. Or a graduated ND filter may have helped.', '2009-06-16 17:20:06.000000', NULL, 1),
(5531550, 797785, 106484, '<td valign="top">Interesting shot, but it looks very flat. Maybe it would look better taken at dawn/dusk with a clear sky so you would maybe get some shadows and different light levels?</td>', 'Interesting shot, but it looks very flat. Maybe it would look better taken at dawn/dusk with a clear sky so you would maybe get some shadows and different light levels?', '2009-06-16 17:23:11.000000', NULL, 1),
